--[[ VoxelIsland builder (spearfishing islands)

HOW TO USE (Roblox Studio, no plugin needed)
  1. Put this Script in ServerScriptService and press Play, OR paste it into the Command Bar.
     It builds Workspace.Islands.VoxelIsland at the origin below.
  2. Or skip this and Insert From File: roblox/VoxelIsland.rbxm (already built from this script).

Folders: Islands/VoxelIsland/{Terrain, Dock, Reef, Buildings, Props, Lighting, Spawns, Tier1, Tier2, Tier3}
Upgrade tiers: Tier1 = humble version, Tier2 = upgraded (also shown at tier 3), Tier3 = extra tier-3 decor.
  Switch with:  require(workspace.Islands.VoxelIsland.IslandTiers).SetTier(workspace.Islands.VoxelIsland, 2)

STUDS: every part uses the same stud look at the same world scale:
  * StudMode = "Inlet"   : Roblox's built-in inset-square surface on every Plastic face (1 square = 1 stud).
  * StudMode = "Variant" : MaterialService.StudInset MaterialVariant (StudsPerTile = 1). Upload
    exports/studs/StudInset_color.png (+ _normal.png) as Decals and paste the ids into StudColorMap/StudNormalMap.
]]
local CONFIG = {
	Origin = Vector3.new(0, 0, 0),
	StartTier = 3,
	StudMode = "Inlet", -- "Inlet" | "Variant" | "None"
	StudColorMap = "", -- e.g. "rbxassetid://123" (Variant mode)
	StudNormalMap = "",
	ApplyLighting = true,
	UseTerrainWater = true,
	ClearExisting = true,
	YieldEvery = 1500,
}

